mapper.select:
select * from orders

    
        and number like concat('%',#{number},'%')
    
    
        and phone like concat('%',#{phone},'%')
    
    
        and user_id = #{userId}
    
    
        and status = #{status}
    
    
        and order_time >= #{beginTime}
    
    
        and order_time <= #{endTime}
    

order by order_time desc

select sum(amount) from orders

    
        and order_time >= #{begin}
    
    
        and order_time < #{end}
    
    
        and status = #{status}

select count(id) from orders

    
        and order_time >= #{begin}
    
    
        and order_time < #{end}
    
    
        and status = #{status}

select max(od.name) as name, sum(od.number) as number from order_detail od inner join orders o on od.order_id = o.id where o.status = 5
and o.order_time >= #{begin}
and o.order_time < #{end}
group by coalesce(od.dish_id, 0), coalesce(od.setmeal_id, 0) order by number desc limit 10
